ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS fieldroutes_appointment_id text; CREATE INDEX IF NOT EXISTS idx_ripple_jobs_fr_appointment ON public.jobs (location_id,fieldroutes_appointment_id) WHERE fieldroutes_appointment_id IS NOT NULL; CREATE OR REPLACE FUNCTION public.ripple_set_job_technicians(p_location_id text, p_ghl_job_id text, p_fieldroutes_appointment_id text, p_source text, p_technicians jsonb) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE n integer; BEGIN IF current_user <> 'service_role' THEN RAISE EXCEPTION 'service_role required'; END IF; IF p_source NOT IN ('fieldroutes','highlevel') THEN RAISE EXCEPTION 'Invalid source'; END IF; IF jsonb_typeof(p_technicians) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Technicians must be a JSON array'; END IF; IF jsonb_array_length(p_technicians)=0 THEN RETURN 0; END IF; IF p_location_id IS NULL OR p_location_id='' OR ((p_ghl_job_id IS NULL OR p_ghl_job_id='') AND (p_fieldroutes_appointment_id IS NULL OR p_fieldroutes_appointment_id='')) THEN RAISE EXCEPTION 'Exact job match required'; END IF; UPDATE public.jobs j SET assigned_technicians=p_technicians, technician_source=p_source, fieldroutes_appointment_id=CASE WHEN p_fieldroutes_appointment_id IS NOT NULL AND p_fieldroutes_appointment_id<>'' THEN p_fieldroutes_appointment_id ELSE j.fieldroutes_appointment_id END WHERE j.location_id=p_location_id AND ((p_ghl_job_id IS NOT NULL AND p_ghl_job_id<>'' AND j.ghl_job_id=p_ghl_job_id) OR (p_fieldroutes_appointment_id IS NOT NULL AND p_fieldroutes_appointment_id<>'' AND j.fieldroutes_appointment_id=p_fieldroutes_appointment_id)) AND (p_source='fieldroutes' OR (j.technician_source IS DISTINCT FROM 'fieldroutes' AND jsonb_array_length(j.assigned_technicians)=0)); GET DIAGNOSTICS n = ROW_COUNT; RETURN n; END $$; REVOKE ALL ON FUNCTION public.ripple_set_job_technicians(text,text,text,text,jsonb) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.ripple_set_job_technicians(text,text,text,text,jsonb) TO service_role;